//#region src/config_services.ts
const isToggleEnabled = (toggle) => {
	if (toggle === void 0) return false;
	if (typeof toggle === "boolean") return toggle;
	return toggle.enabled !== false;
};
/** Postgres is omitted because every project includes it. */
const declaredNeonServices = (config) => {
	const services = [];
	if (isToggleEnabled(config.auth)) services.push("auth");
	if (isToggleEnabled(config.dataApi)) services.push("data-api");
	if (Object.keys(config.preview?.buckets ?? {}).length > 0) services.push("object-storage");
	if (Object.keys(config.preview?.functions ?? {}).length > 0) services.push("functions");
	if (isToggleEnabled(config.preview?.aiGateway)) services.push("ai-gateway");
	return services;
};
//#endregion
export { declaredNeonServices };
